package com.goldenaccountant.core.chart

/** شجرة الحسابات الأصلية كما في قاعدة البيانات المرجعية. */
data class GroupSeed(val id: Long, val name: String, val parentId: Long)
data class AccountSeed(val id: Long, val name: String, val groupId: Long)

object ChartOfAccounts {
    private const val GROUPS =
        "1,اصول,0;2,التزامات وحقوق الملكية,0;3,مصروفات,0;4,ايرادات,0;11,اصول ثابتة,1;12,اصول متداولة,1;21,حقوق الملكية,2;22,التزامات متداولة,2;23,التزامات ثابتة,2;31,تكاليف النشاط,3;32,مصاريف تشغيلية وإدارية,3;41,ايرادات النشاط,4;42,إيرادات أخرى,4;121,الصناديق,12;122,البنوك,12;123,العملاء,12;124,اخرى,12;125,البضاعة,12;211,راس المال,21;212,الأرباح والخسائر,21;213,المسحوبات,21;214,المساهمين,21;221,الموردون,22;311,المشتريات,31;312,مردودات مبيعات,31;313,الخصم المسموح به,31;314,تسوية المخزون,31;315,الأصناف التالفة,31;321,مصاريف النشاط,32;322,مصاريف عمومية وادارية,32;323,مصاريف أخرى,32;411,المبيعات,41;412,مردودات مشتريات,41;413,الخصم المكتسب,41"
    private const val SYSTEM =
        "-30,تسوية المخزون-صرف وتوريد,314;-27,فوارق بيع وشراء العملات,42;-24,اجور نقل,322;-20,رسوم أخرى,323;-18,الضريبة,22;-17,ح/الارباح والخسائر,212;-16,البضاعة التالفة,314;-15,عجز و زيادة البضاعة,314;-14,بضاعة أول المدة,125;-13,رأس المال,211;-12,مردودات مشتريات نقدي,412;-11,مردودات مبيعات نقدي,312;-10,مردودات مشتريات آجل,412;-9,مردودات مبيعات آجل,312;-8,الخصم المسموح به,313;-7,الخصم المكتسب,413;-6,مشتريات نقدي,311;-5,مبيعات نقدي,411;-3,الصندوق,121;-2,مشتريات آجل,311;-1,مبيعات آجل,411;-41,تكلفة المبيعات,31;-40,المخزون,125"

    val groups: List<GroupSeed> = GROUPS.split(";").map { r -> r.split(",").let { GroupSeed(it[0].toLong(), it[1], it[2].toLong()) } }
    val systemAccounts: List<AccountSeed> = SYSTEM.split(";").map { r -> r.split(",").let { AccountSeed(it[0].toLong(), it[1], it[2].toLong()) } }

    /** طبيعة الحساب من الجذر: 1 أصول و3 مصروفات = مدينة. */
    fun isDebitNature(groupId: Long): Boolean = groupId.toString().first() in "13"
}
